import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import productService from "../services/productService";
import categoryService from "../services/categoryService";
import ProductCard from "../components/ProductCard";
import Loader from "../components/Loader";

const getCategoryIcon = (name) => {
  const lowercaseName = name.toLowerCase();
  if (lowercaseName.includes("địa hình") || lowercaseName.includes("mtb")) return "⛰️";
  if (lowercaseName.includes("đua") || lowercaseName.includes("road")) return "🚴";
  if (lowercaseName.includes("thành phố") || lowercaseName.includes("touring")) return "🏙️";
  if (lowercaseName.includes("trẻ em")) return "🧸";
  if (lowercaseName.includes("điện") || lowercaseName.includes("trợ lực")) return "⚡";
  return "🚲";
};

export default function HomePage() {
  const [featured, setFeatured] = useState([]);
  const [newest, setNewest] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const [f, n, c] = await Promise.all([
          productService.getFeatured(),
          productService.getNewest(),
          categoryService.getAll(),
        ]);
        setFeatured(f.data);
        setNewest(n.data);
        setCategories(c.data);
      } catch (err) {
        console.error("Lỗi khi tải dữ liệu trang chủ:", err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div className="bg-slate-50/50 min-h-screen overflow-x-hidden relative">

      {/* 1. Hero Section - Hiệu ứng ánh sáng bất đối xứng */}
      <section className="relative bg-slate-900 text-white overflow-hidden min-h-[480px] sm:min-h-[560px] flex items-center">
        <div
          className="absolute inset-0 opacity-[0.12] pointer-events-none"
          style={{
            backgroundImage:
              "repeating-linear-gradient(115deg, transparent, transparent 50px, #a3e635 50px, #a3e635 52px)",
          }}
        />
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-lime-500/10 blur-[120px] rounded-full pointer-events-none -mr-40 -mt-40 animate-pulse duration-[6000ms]" />
        <div className="absolute bottom-0 left-0 w-[350px] h-[350px] bg-blue-500/10 blur-[100px] rounded-full pointer-events-none -ml-20 -mb-20 animate-pulse duration-[4000ms]" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 py-20 sm:py-28 relative z-10 w-full animate-fade-in-up">
          <p className="text-lime-400 font-extrabold tracking-[0.25em] text-xs sm:text-sm uppercase mb-4 drop-shadow-sm">
            Hệ thống xe đạp chuyên nghiệp
          </p>
          <h1 className="font-black text-4xl sm:text-6xl leading-[1.15] max-w-3xl tracking-tight text-white">
            ĐẠP NHANH HƠN.
            <br />
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-lime-400 to-emerald-400">
              ĐI XA HƠN.
            </span>
          </h1>
          <p className="text-slate-300 mt-6 max-w-xl text-sm sm:text-base leading-relaxed font-medium opacity-90">
            Từ đường đua tốc độ chuẩn quốc tế đến những cung đường off-road gồ ghề, BikeShop mang đến những chiếc xe được tinh tuyển kỹ lưỡng từ các thương hiệu hàng đầu thế giới.
          </p>
          <div className="mt-10">
            <Link
              to="/products"
              className="inline-flex items-center gap-2 bg-gradient-to-r from-lime-400 to-lime-500 text-slate-900 font-black px-8 py-3.5 rounded-xl shadow-lg shadow-lime-500/20 hover:shadow-lime-500/40 hover:-translate-y-1 hover:scale-102 transition-all duration-300 text-sm tracking-wide"
            >
              Khám phá ngay <span>→</span>
            </Link>
          </div>
        </div>
      </section>

      {/* === ĐOẠN ĐƯỜNG XE ĐẠP CHẠY QUA CHẠY LẠI ĐỘC ĐÁO === */}
      <div className="w-full h-10 bg-slate-800 relative overflow-hidden border-y border-white/5 shadow-inner select-none pointer-events-none z-20">
        {/* Vạch kẻ đường đứt đoạn chuyển động ngược hướng tạo cảm giác xe tiến lên */}
        <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-[2px] bg-dashed-road opacity-30 animate-road-move" />

        {/* Khối chứa chiếc xe đạp chuyển động lặp vô hạn qua 2 rìa màn hình */}
        <div className="absolute top-1/2 -translate-y-1/2 text-2xl animate-bike-ride">
          🚴💨
        </div>
      </div>

      {/* 2. Categories Section */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 py-16 relative z-10">
        <div className="mb-8">
          <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            <span className="w-1.5 h-6 bg-slate-900 rounded-full animate-bounce" />
            Danh mục xe đạp
          </h2>
        </div>
        {loading ? (
          <div className="py-6"><Loader small /></div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
            {categories.map((cat) => (
              <Link
                key={cat.id}
                to={`/products?categoryId=${cat.id}`}
                className="group bg-white border border-slate-100 rounded-2xl p-6 text-center shadow-sm hover:shadow-xl hover:border-lime-500/40 hover:-translate-y-1.5 transition-all duration-300 flex flex-col items-center justify-center gap-3"
              >
                <div className="w-12 h-12 rounded-xl bg-slate-50 flex items-center justify-center text-2xl group-hover:bg-lime-50 group-hover:scale-110 transition-all duration-300">
                  {getCategoryIcon(cat.name)}
                </div>
                <p className="font-bold text-slate-700 text-xs sm:text-sm group-hover:text-slate-900 transition-colors">
                  {cat.name}
                </p>
              </Link>
            ))}
          </div>
        )}
      </section>

      {/* 3. Featured Products Section */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 py-12 relative z-10">
        <div className="flex items-end justify-between mb-8 border-b border-slate-100 pb-4">
          <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            <span className="w-1.5 h-6 bg-blue-600 rounded-full" />
            Sản phẩm nổi bật
          </h2>
          <Link 
            to="/products" 
            className="text-xs sm:text-sm font-bold text-blue-600 hover:text-blue-700 hover:translate-x-0.5 transition-all duration-200 flex items-center gap-1"
          >
            Xem tất cả <span className="text-xs">→</span>
          </Link>
        </div>
        {loading ? (
          <div className="py-12"><Loader /></div>
        ) : (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
            {featured.map((p) => (
              <ProductCard key={p.id} product={p} />
            ))}
          </div>
        )}
      </section>

      {/* 4. Newest Products Section */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 py-12 mb-16 relative z-10">
        <div className="flex items-end justify-between mb-8 border-b border-slate-100 pb-4">
          <h2 className="text-xl sm:text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            <span className="w-1.5 h-6 bg-rose-500 rounded-full" />
            Bộ sưu tập mới về
          </h2>
        </div>
        {loading ? (
          <div className="py-12"><Loader /></div>
        ) : (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6">
            {newest.map((p) => (
              <ProductCard key={p.id} product={p} />
            ))}
          </div>
        )}
      </section>

      {/* NHÚNG CSS ANIMATIONS ĐỂ LAYOUT CHẠY ĐỘNG MƯỢT MÀ */}
      <style>{`
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(15px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
          animation: fadeInUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
        }

        /* Hiệu ứng xe đạp lướt từ trái sang phải vô tận */
        @keyframes bikeRun {
          0% { left: -10%; transform: scaleX(1); }
          48% { transform: scaleX(1); }
          50% { left: 110%; transform: scaleX(-1); } /* Quay đầu xe khi đi hết rìa */
          98% { transform: scaleX(-1); }
          100% { left: -10%; transform: scaleX(1); }
        }
        .animate-bike-ride {
          position: absolute;
          animation: bikeRun 14s linear infinite;
        }

        /* Hiệu ứng vạch đường chạy ngược chiều xe */
        @keyframes roadMove {
          from { background-position-x: 0px; }
          to { background-position-x: 120px; }
        }
        .bg-dashed-road {
          background-image: linear-gradient(90deg, #fff 50%, transparent 50%);
          background-size: 30px 100%;
        }
        .animate-road-move {
          animation: roadMove 2s linear infinite;
        }
      `}</style>
    </div>
  );
}
